# Read the public outline titles without importing any private snapshot.
import re
source=Path('academy/apps/learner/lib/course_content.dart').read_text()
outline={int(k):re.findall(r"'([^']+)'",v) for k,v in re.findall(r"(\d+): \[(.*?)\]",source.split('const draftOutlines')[1].split('};')[0])}
def dart(value): return json.dumps(value,ensure_ascii=False).replace('$','\\$')
rows=["part of 'course_content.dart';",'const extendedTopics = <Topic>[']; activities=[]; fixtures=[]
for chapter, entries in units.items():
 assert len(entries)==len(outline[chapter]),(chapter,len(entries),len(outline[chapter]))
 for index,(concept,example,prompt,solution,cases) in enumerate(entries):
  tid=f'python-c{chapter}-t{index}';title=outline[chapter][index]
  lesson=concept+'\n\nRead the example before running it. Predict the result and record why. Run it in the terminal below, compare your prediction with the result, then change one value. Identify which behaviour stays the same and which changes.\n\nCheck your understanding: explain the rule in your own words, use a different input, and describe one situation where the rule matters. Save your explanation in My Notes.'
  rows.append('Topic('+','.join([dart(tid),str(chapter),dart(title),'goal:'+dart('Understand '+title.lower()+', test an example, and apply it independently.'),'lesson:'+dart(lesson),'example:'+dart(example),'output:'+dart('Run the example and compare its output with your prediction.')])+'),')
  tests=[]
  for args,expected in cases:
   values=args if isinstance(args,tuple) else (args,)
   harness='print(solve('+', '.join(repr(v) for v in values)+'))'
   test={'input':[],'harness':harness,'expected':expected}
   if re.fullmatch(r'-?\d+(?:\.\d+)?',expected): test.update(comparison='numeric',tolerance=0.000001)
   tests.append(test)
   fixtures.append({'code':solution,'harness':harness,'expected':expected})
  if chapter==3 and index==2:
   for invalid in [0,-2]:
    harness=f'try:\n    solve({invalid})\nexcept ValueError:\n    print("ValueError")\nelse:\n    print("No exception")'
    tests.append({'input':[],'harness':harness,'expected':'ValueError'})
    fixtures.append({'code':solution,'harness':harness,'expected':'ValueError'})
  activities.append({'id':f'extended-c{chapter}-t{index}-work','topic':tid,'category':'Classwork','type':'written','title':'Explain and predict','prompt':f'For the example in {title}, predict the output before running it. Explain why each result occurs. Then change one input or value and predict the new result.','hints':['Which value or rule changes between the two runs?','Trace one step at a time and compare your prediction with the actual result.'],'required':False})
  activities.append({'id':f'extended-c{chapter}-t{index}-assignment','topic':tid,'category':'Homework','type':'code','title':title+' — independent task','prompt':prompt+'\n\nRecord any requested explanation in My Notes.','tests':tests,'hints':['Write down the input, required result, and one small example.','Try a boundary or empty case allowed by the question. Which part of your reasoning needs adjustment?'],'solution':solution,'required':False})
rows+= ['];','const extendedExercises = <Exercise>[']
for a in activities: rows.append('Exercise('+','.join(k+':'+dart(v) for k,v in a.items())+'),')
rows+= ['];'];Path('academy/apps/learner/lib/extended_content.dart').write_text('\n'.join(rows)+'\n')
Path('academy/scripts/extended_reference_checks.json').write_text(json.dumps(fixtures,indent=2))
Path('academy/scripts/extended_example_checks.json').write_text(json.dumps([x[1] for group in units.values() for x in group],indent=2))
print('Authored',sum(map(len,units.values())),'extended topic lessons and',len(activities),'practice tasks')
